.toast-container {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 9999;
    display: flex;
    flex-direction: column-reverse;
    align-items: flex-end;
    gap: 0.65rem;
    pointer-events: none;
    padding-bottom: env(safe-area-inset-bottom, 0);
    padding-right: env(safe-area-inset-right, 0)
}

.toast {
    pointer-events: auto;
    display: grid;
    grid-template-columns: 1fr auto;
    column-gap: 0.9rem;
    max-width: 22rem;
    width: max-content;
    background: #FFF;
    color: #000;
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 14px;
    padding: 12px 14px;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    box-shadow: 0 18px 50px rgba(0, 0, 0, 0.35), 0 4px 16px rgba(0, 0, 0, 0.25);
    text-decoration: none;
    overflow: clip;
    transform-origin: right bottom;
    animation: toast-in 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
    position: relative
}

.toast:before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06)
}

.toast:hover {
    transform: translateY(-2px);
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45), 0 6px 20px rgba(0, 0, 0, 0.35)
}

.toast__content {
    display: grid;
    grid-template-columns: auto 1fr;
    column-gap: 0.6rem;
    align-items: start
}

.toast__icon {
    width: 28px;
    height: 28px;
    border-radius: 8px;
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0.05));
    display: grid;
    place-items: center;
    color: #000;
    font-size: 16px;
    line-height: 1;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12)
}

.toast__text {
    min-width: 0
}

.toast__title {
    font-weight: 700;
    font-size: 0.98rem;
    line-height: 1.25rem;
    letter-spacing: 0.2px;
    margin: 0 0 0.15rem;
    color: #000;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis
}

.toast__body {
    margin-top: 2px;
    font-size: 0.86rem;
    line-height: 1.2rem;
    color: #000;
    overflow-wrap: anywhere
}

.toast__close {
    appearance: none;
    border: 0;
    background: transparent;
    color: #000;
    font-size: 1.2rem;
    line-height: 1;
    padding: 0.1rem 0.25rem;
    margin: -0.2rem -0.1rem 0 0;
    border-radius: 8px;
    cursor: pointer;
    transition: transform 0.12s ease, background-color 0.12s ease, color 0.12s ease
}

.toast__close:hover {
    color: #000;
    background: rgba(255, 255, 255, 0.08);
    transform: scale(1.06)
}

.toast__progress {
    position: absolute;
    left: 10px;
    right: 10px;
    bottom: 8px;
    height: 3px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.12);
    overflow: hidden
}

.toast__progress::after {
    content: "";
    display: block;
    height: 100%;
    width: 100%;
    background: linear-gradient(90deg, #FFF, var(--color_primary));
    transform-origin: left center;
    animation: toast-progress 10s linear forwards;
    box-shadow: 0 0 18px rgba(139, 92, 246, 0.45)
}

.toast--out {
    animation: toast-out 220ms ease-in forwards
}

@media (prefers-reduced-motion:reduce) {
    .toast {
        animation: none
    }
    .toast--out {
        animation: none;
        opacity: 0
    }
    .toast__progress::after {
        animation-duration: 0s;
        width: 0
    }
}

@keyframes toast-in {
    0% {
        opacity: 0;
        transform: translateY(14px) scale(0.98);
        filter: blur(3px)
    }
    60% {
        opacity: 1;
        transform: translateY(-2px) scale(1.01);
        filter: blur(0)
    }
    100% {
        opacity: 1;
        transform: translateY(0) scale(1)
    }
}

@keyframes toast-out {
    to {
        opacity: 0;
        transform: translateY(10px) scale(0.98);
        filter: blur(1px)
    }
}

@keyframes toast-progress {
    from {
        transform: scaleX(1)
    }
    to {
        transform: scaleX(0)
    }
}

