    animation: rotate-in 0.5s
}

.floating_menu_calendar_links a#menu-share:hover>i {
    animation: rotate-out 0.5s
}

@keyframes bot-to-top {
    0% {
        bottom: -20px
    }
    50% {
        bottom: 20px
    }
}

@keyframes scale-in {
    from {
        transform: scale(0);
        opacity: 0
    }
    to {
        transform: scale(1);
        opacity: 1
    }
}

@keyframes rotate-in {
    from {
        transform: rotate(0deg)
    }
    to {
        transform: rotate(360deg)
    }
}

@keyframes rotate-out {
    from {
        transform: rotate(360deg)
    }
    to {
        transform: rotate(0deg)
    }
}

