    display: inline-block;
    cursor: pointer
}

.filters_meals_body .card_meal_img_unit img {
    border-radius: 10px;
    object-fit: cover;
    object-position: center center;
    border: 2px solid #fff;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    margin: 5px
}

.filters_meals_body .horizontal-card {
    min-height: 130px;
    background: white;
    position: relative;
    border-radius: 15px;
    padding: 5px
}

.filters_meals_body .horizontal-card .premium_bookmark {
    position: absolute;
    top: 15px;
    left: 15px
}

.filters_meals_body .horizontal-card .premium_bookmark i {
    font-size: 25px;
    filter: drop-shadow(0px 0px 2px #363636)
}

.filters_meals_body .horizontal-card-image {
    height: auto;
    width: 120px;
    float: left;
    margin-right: 1em;
    border-radius: 10px
}

.filters_meals_body .horizontal-card-image img {
    border-radius: 10px;
    object-fit: cover;
    object-position: center center;
    border: 2px solid #fff;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)
}

.filters_meals_body .horizontal-card-details {
    width: 100%;
    padding-top: 5px
}

.filters_meals_body .horizontal-card-details .calories {
    margin: 5px 0px 0px 0px;
