    content: "";
    font-family: "Font Awesome 5 Free";
    font-weight: 900;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    font-size: 16px
}

.checkbox-round input[type="checkbox"] {
    visibility: hidden
}

