.notif-bell {
    position: relative;
    margin-left: auto;
    display: flex;
    align-items: center;
    padding: 0 4px;
    flex-shrink: 0
}

.notif-bell__btn {
    position: relative;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: transparent;
    border: none;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background 0.18s;
    color: #444;
    outline: none
}

.notif-bell__btn:hover {
    background: rgba(0, 0, 0, 0.07)
}

.notif-bell__btn:focus {
    background: rgba(0, 0, 0, 0.07)
}

.notif-bell__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.15s
}

.notif-bell__badge {
    position: absolute;
    right: 0px;
    top: -4px;
    min-width: 16px;
    height: 16px;
    background: #ca0001;
    color: #fff;
    font-size: 9px;
    font-weight: 700;
    font-family: Poppins, sans-serif;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
    line-height: 1;
    border: 2px solid #fff;
    box-sizing: content-box;
    z-index: 1
}

.notif-bell__badge[data-count="0"],
.notif-bell__badge:empty {
    display: none
}

.notif-panel {
    position: absolute;
    top: calc(100% + 14px);
    right: -4px;
    width: 390px;
    background: #fff;
    border-radius: 18px;
    box-shadow: 0 24px 64px rgba(0, 0, 0, 0.13), 0 6px 20px rgba(0, 0, 0, 0.07);
    overflow: visible;
    z-index: 99999;
    transform-origin: top right;
    transform: scale(0.95) translateY(-6px);
    opacity: 0;
    pointer-events: none;
    transition: transform 0.22s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.2s ease
}

.notif-panel.is-open {
    transform: scale(1) translateY(0);
    opacity: 1;
    pointer-events: all
}

.notif-panel::before {
    content: '';
    position: absolute;
    top: -5px;
    right: 20px;
    width: 11px;
    height: 11px;
    background: #fff;
    transform: rotate(45deg);
    box-shadow: -2px -2px 5px rgba(0, 0, 0, 0.04);
    border-radius: 2px 0 0 0;
    z-index: 1
}

.notif-panel__header {
    display: flex;
    align-items: center;
    padding: 14px 16px 12px;
    border-bottom: 1px solid #f3f3f3;
    gap: 6px;
    flex-wrap: nowrap;
    min-width: 0
}

.notif-panel__title {
    font-size: 14px;
    font-weight: 700;
    color: #111;
    font-family: Poppins, sans-serif;
    letter-spacing: -0.01em;
    flex-shrink: 0
}

.notif-panel__unread-pill {
    font-size: 10px;
    font-weight: 700;
    background: #40dd85;
    color: #fff;
    padding: 2px 7px;
    border-radius: 20px;
    font-family: Poppins, sans-serif;
    line-height: 1.6;
    display: none;
    flex-shrink: 0;
    white-space: nowrap
}

.notif-panel__unread-pill.has-count {
    display: inline-flex
}

.notif-filter {
    margin-left: auto
}

.notif-panel__mark-all {
    font-size: 12px;
    color: #00bb86;
    font-weight: 600;
    cursor: pointer;
    background: none;
    border: none;
    padding: 4px 0;
    font-family: Poppins, sans-serif;
    white-space: nowrap;
    transition: opacity 0.15s;
    outline: none
}

.notif-panel__mark-all:hover {
    opacity: 0.65
}

.notif-filter {
    position: relative;
    margin-left: auto
}

.notif-filter__btn {
    display: flex;
    align-items: center;
    gap: 5px;
    padding: 5px 10px;
    background: #f5f5f5;
    border: 1.5px solid #ececec;
    border-radius: 8px;
    cursor: pointer;
    outline: none;
    font-size: 11px;
    font-weight: 600;
    font-family: Poppins, sans-serif;
    color: #444;
    white-space: nowrap;
    transition: border-color 0.15s, background 0.15s;
    user-select: none
}

.notif-filter__btn:hover {
