    transform-origin: top right;
    transition: opacity 0.15s ease, transform 0.15s ease
}

.notif-filter.is-open .notif-filter__menu {
    opacity: 1;
    pointer-events: all;
    transform: scale(1) translateY(0)
}

.notif-filter__opt {
    display: flex;
    align-items: center;
    gap: 8px;
