    border-radius: 8px;
    font-size: 12px;
    font-weight: 500;
    font-family: Poppins, sans-serif;
    color: #444;
    cursor: pointer;
    text-align: left;
    transition: background 0.1s;
    outline: none;
    white-space: nowrap
}

.notif-filter__opt:hover {
    background: #f5f5f5
}

.notif-filter__opt.is-active {
    background: #f0fdf8;
