@keyframes bell-ring {
    0%,
    100% {
        transform: rotate(0)
    }
    10% {
        transform: rotate(16deg)
    }
    20% {
        transform: rotate(-13deg)
    }
    30% {
        transform: rotate(10deg)
    }
    40% {
        transform: rotate(-8deg)
    }
    50% {
        transform: rotate(5deg)
    }
    60% {
        transform: rotate(-3deg)
    }
    70% {
        transform: rotate(2deg)
    }
}

