.onboarding-toasts {
    position: fixed;
    right: 18px;
    bottom: 18px;
    z-index: 10800;
    display: flex;
    flex-direction: column;
    gap: 8px;
    align-items: flex-end;
    max-width: min(420px, calc(100vw - 36px));
    pointer-events: none
}

.onboarding-toast {
    pointer-events: auto;
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 11px 13px;
    border-radius: 10px;
    font-size: 13px;
    font-weight: 600;
    line-height: 1.4;
    box-shadow: 0 10px 30px -12px rgba(15, 23, 42, 0.45);
    animation: obToastIn 0.18s ease-out both
}

.onboarding-toast__t {
    min-width: 0;
    overflow-wrap: anywhere
}

.onboarding-toast--ok {
    background: #065f46;
    border: 1px solid #047857;
    color: #ecfdf5
}

.onboarding-toast--bad {
    background: #fff;
    border: 1px solid #fecaca;
    border-left: 3px solid #b91c1c;
    color: #7f1d1d;
    font-weight: 600
}

.onboarding-toast__x {
    border: 0;
    background: none;
    padding: 0 2px;
    margin-left: auto;
    cursor: pointer;
    font-size: 17px;
    line-height: 1;
    color: #b91c1c;
    flex: 0 0 auto
}

.onboarding-toast.is-going {
    animation: obToastOut 0.2s ease-in both
}

@keyframes obToastIn {
    from {
        opacity: 0;
        transform: translateY(8px)
    }
    to {
        opacity: 1;
        transform: none
    }
}

@keyframes obToastOut {
    from {
        opacity: 1
    }
    to {
        opacity: 0;
        transform: translateY(6px)
    }
}

@media (prefers-reduced-motion:reduce) {
    .onboarding-toast,
    .onboarding-toast.is-going {
        animation: none
    }
}

.ob-fs {
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
    flex: 0 0 auto;
    transition: opacity 0.2s ease
}

.ob-fs--saved {
