#integrationsModal .modal-dialog.small_modal_action {
    display: flex;
    flex-direction: column;
    max-height: calc(100vh - 3.5rem) !important;
    min-width: 0;
    max-width: 760px;
    width: calc(100% - 32px);
    margin: 1.75rem auto;
    box-shadow: 0 24px 60px -20px rgba(15, 23, 42, 0.35)
}

#integrationsModal .modal-content.small_modal_action_content {
    flex: 1 1 auto;
