    background-position: right 12px center;
    padding-right: 32px
}

#integrationsModal .integration-form {
    scrollbar-width: thin;
    scrollbar-color: #cbd5e1 #eef2f6
}

#integrationsModal .integration-form::-webkit-scrollbar {
    width: 10px
}

#integrationsModal .integration-form::-webkit-scrollbar-button {
    display: none;
    height: 0
}

#integrationsModal .integration-form::-webkit-scrollbar-track {
    background: #f4f6f8
}

#integrationsModal .integration-form::-webkit-scrollbar-thumb {
    background: #cbd5e1;
    border-radius: 99px;
    border: 3px solid #f4f6f8;
