#integrationsModal .integration-form::-webkit-scrollbar-thumb:hover {
    background: #94a3b8;
    background-clip: padding-box
}

[data-tour],
.shepherd-target {
    scroll-margin-top: 180px
}

.shepherd-element.training-tip {
    z-index: 100001;
    max-width: 360px;
    background: #fff;
    border: 1px solid #c7d2fe;
    border-radius: 14px;
    box-shadow: 0 24px 60px -12px rgba(15, 23, 42, 0.45)
}

.shepherd-element.training-tip .shepherd-content {
    border-radius: 14px;
    overflow: hidden;
    background: #fff
}

.shepherd-element.training-tip .shepherd-arrow::before {
    background: #fff
}

.shepherd-element.training-tip.shepherd-has-title .shepherd-content .shepherd-header {
    background: #fff;
    align-items: flex-start;
    padding: 14px 15px 0;
    line-height: 1.3
}

.shepherd-element.training-tip .shepherd-title {
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-size: 14.5px;
    font-weight: 700;
    color: #0f172a
}

.shepherd-element.training-tip .training-tip__eyebrow {
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.11em;
    text-transform: uppercase;
    color: #4338ca
}

.shepherd-element.training-tip .training-tip__name {
    font-size: 14.5px;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.3
}

.shepherd-element.training-tip.shepherd-has-title .shepherd-content .shepherd-cancel-icon {
    font-size: 20px;
    line-height: 1;
    width: 24px;
    height: 24px;
    border-radius: 6px;
    color: #94a3b8;
    flex: none
}

.shepherd-element.training-tip.shepherd-has-title .shepherd-content .shepherd-cancel-icon:hover {
    background: #f8fafc;
    color: #1e293b
}

.shepherd-element.training-tip .shepherd-text {
    padding: 8px 15px 14px;
    font-size: 13px;
    line-height: 1.55;
    color: #475569
}

.shepherd-element.training-tip .shepherd-footer {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 11px 15px;
    background: #fafbfc;
    border-top: 1px solid #eef2f7;
    border-bottom-left-radius: 14px;
    border-bottom-right-radius: 14px;
    justify-content: flex-start
}

.shepherd-element.training-tip .shepherd-footer .shepherd-button:first-of-type {
    margin-left: auto
}

.shepherd-element.training-tip .training-tip__meta {
    display: flex;
    align-items: center;
    gap: 8px
}

.shepherd-element.training-tip .training-tip__count {
    font-size: 11.5px;
    font-weight: 700;
    color: #64748b;
    font-variant-numeric: tabular-nums;
    white-space: nowrap
}

.shepherd-element.training-tip .training-tip__dots {
    display: flex;
    gap: 4px
}

.shepherd-element.training-tip .training-tip__dots i {
    width: 5px;
    height: 5px;
    border-radius: 999px;
    background: #cbd5e1
}

.shepherd-element.training-tip .training-tip__dots i.on {
    background: #4338ca
}

.shepherd-element.training-tip .shepherd-button {
    margin-right: 0;
    padding: 6px 12px;
    border-radius: 9px;
    font-size: 12px;
    font-weight: 600;
    color: #fff;
    background: linear-gradient(135deg, #6366f1, #4338ca);
    box-shadow: 0 4px 14px -4px rgba(15, 23, 42, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.28);
    transition: transform 0.15s, box-shadow 0.15s, background 0.15s
}

.shepherd-element.training-tip .shepherd-button:not(:disabled):hover {
    background: linear-gradient(135deg, #4338ca, #3730a3);
    color: #fff;
    transform: translateY(-1px);
    box-shadow: 0 10px 22px -8px rgba(15, 23, 42, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.28)
}

.shepherd-element.training-tip .shepherd-button.shepherd-button-secondary {
    background: #fff;
    color: #475569;
    border: 1px solid #e5e7eb;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04)
}

.shepherd-element.training-tip .shepherd-button.shepherd-button-secondary:not(:disabled):hover {
    background: #f8fafc;
    color: #1e293b
}

.shepherd-element.training-tip .shepherd-button:disabled {
    opacity: 0.45;
    transform: none
}

.shepherd-enabled.shepherd-target {
    position: relative;
    z-index: 100000;
    border-radius: 9px;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.9), 0 0 22px 3px rgba(99, 102, 241, 0.45)
}

body .shepherd-modal-overlay-container.shepherd-modal-is-visible {
    opacity: 0.62;
    z-index: 100000
}

.training-tip__safe {
    margin-top: 10px;
    padding: 8px 10px;
    border-radius: 6px;
    background: #fef3c7;
    border: 1px solid #fcd34d;
    color: #92400e;
    font-size: 12px;
    line-height: 1.45
}

.training-hud {
    position: fixed;
    left: 20px;
    bottom: 20px;
    z-index: 10050;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 9px 8px 16px;
    border-radius: 999px;
    background: #0f172a;
    color: #e2e8f0;
    font-size: 13px;
    font-weight: 600;
    box-shadow: 0 10px 26px -8px rgba(15, 23, 42, 0.6)
}

.training-hud__action,
.training-hud__exit {
    border: 0;
    border-radius: 999px;
    padding: 5px 12px;
    font-size: 12px;
    font-weight: 700;
    color: #fff;
    background: rgba(255, 255, 255, 0.12);
    cursor: pointer
}

.training-hud__action:hover,
.training-hud__exit:hover {
    background: rgba(255, 255, 255, 0.22)
}

.training-page {
    --t-accent: #4338ca;
    --t-accent-soft: #6366f1;
    --t-accent-deep: #3730a3;
    --t-accent-bg: #eef2ff;
    --t-accent-border: #c7d2fe;
    padding: 24px;
    max-width: 1180px;
    margin: 0 auto;
    font-size: 14px;
    color: #1e293b
}

.training-page__header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 20px;
    flex-wrap: wrap;
    padding-bottom: 18px;
    border-bottom: 1px solid #e5e7eb;
    margin-bottom: 22px
}

.training-page__eyebrow {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--t-accent);
    margin-bottom: 7px
}

.training-page__title {
    font-size: 32px;
    font-weight: 700;
    line-height: 1.1;
    letter-spacing: -0.02em;
    color: #0f172a;
    margin: 0
}

.training-page__sub {
    margin-top: 8px;
    font-size: 13.5px;
    color: #64748b;
    max-width: 62ch
}

.training-page__section-label {
    display: flex;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 13px
}

.training-page__section-label strong {
    font-size: 15px;
    font-weight: 700;
    color: #0f172a
}

.training-page__section-label span {
    font-size: 12.5px;
    color: #94a3b8
}

.training-page__empty {
    padding: 40px 24px;
    text-align: center;
    border: 1px dashed #cbd5e1;
    border-radius: 14px;
    color: #64748b;
    background: #f8fafc
}

.training-banner {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    padding: 12px 15px;
    margin-bottom: 20px;
    border-radius: 9px;
    background: #eff6ff;
    border: 1px solid #bfdbfe;
    border-left: 4px solid var(--t-accent);
    font-size: 13.5px
}

.training-banner__actions {
    margin-left: auto;
    display: flex;
    gap: 8px
}

.training-hero {
    position: relative;
    overflow: hidden;
    display: flex;
    align-items: center;
    gap: 26px;
    flex-wrap: wrap;
    padding: 24px 26px;
    margin-bottom: 22px;
    border-radius: 18px;
    color: #fff;
    background: linear-gradient(135deg, #6366f1 0%, #4338ca 55%, #3730a3 100%);
    box-shadow: 0 18px 40px -16px rgba(67, 56, 202, 0.45), 0 4px 12px -4px rgba(15, 23, 42, 0.18)
}

.training-hero::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.28;
    background-image: radial-gradient(rgba(255, 255, 255, 0.55) 1px, transparent 1px);
    background-size: 15px 15px
}

.training-hero__body {
    position: relative;
    z-index: 1;
    flex: 1 1 340px;
    min-width: 0
}

.training-hero__eyebrow {
    font-size: 10.5px;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.82);
    margin-bottom: 8px
}

.training-hero__title {
    font-size: 23px;
    font-weight: 800;
    letter-spacing: -0.015em;
    margin-bottom: 6px
}

.training-hero__text {
    font-size: 13.5px;
    color: rgba(255, 255, 255, 0.86);
    max-width: 56ch;
    margin: 0
}

.training-hero__meta {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    gap: 11px;
    align-items: flex-start
}

.training-hero__stats {
    display: flex;
    gap: 9px;
    flex-wrap: wrap
}

.training-hero__stat {
    background: rgba(255, 255, 255, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.24);
    border-radius: 999px;
    padding: 4px 11px;
    font-size: 11.5px;
    font-weight: 700;
    font-variant-numeric: tabular-nums
}

.training-hero__btn {
    border: 0;
    background: #fff;
    color: #3730a3;
    padding: 9px 17px;
    border-radius: 9px;
    font-size: 13.5px;
    font-weight: 700;
    cursor: pointer;
    box-shadow: 0 6px 18px -6px rgba(15, 23, 42, 0.5);
    transition: transform 0.15s, box-shadow 0.15s
}

.training-hero__btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 12px 26px -8px rgba(15, 23, 42, 0.6)
}

.training-kpis {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 24px
}

@media (max-width:900px) {
    .training-kpis {
        grid-template-columns: repeat(2, 1fr)
    }
}

.training-kpi {
    position: relative;
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 14px;
    padding: 15px 17px 15px 20px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
    overflow: hidden
}

.training-kpi::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: var(--t-accent)
}

.training-kpi__label {
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b
}

.training-kpi__value {
    font-size: 24px;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.15;
    font-variant-numeric: tabular-nums
}

.training-kpi__value small {
    font-size: 14px;
    color: #94a3b8;
    font-weight: 600
}

.training-kpi__hint {
    font-size: 11.5px;
    color: #94a3b8
}

.training-tracks {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px
}

@media (max-width:900px) {
    .training-tracks {
        grid-template-columns: 1fr
    }
}

.training-track {
    position: relative;
    display: flex;
    flex-direction: column;
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 14px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
    overflow: hidden;
    transition: transform 0.15s, box-shadow 0.15s, border-color 0.15s;
    --tone: #4338ca;
    --tone-bg: #eef2ff;
    --tone-border: #c7d2fe;
    --tone-deep: #3730a3
}

.training-track--emerald {
    --tone: #047857;
    --tone-bg: #ecfdf5;
    --tone-border: #a7f3d0;
    --tone-deep: #065f46
}

.training-track--blue {
    --tone: #1d4ed8;
    --tone-bg: #eff6ff;
    --tone-border: #bfdbfe;
    --tone-deep: #1e40af
}

.training-track--violet {
    --tone: #6d28d9;
    --tone-bg: #f5f3ff;
    --tone-border: #ddd6fe;
    --tone-deep: #5b21b6
}

.training-track--slate {
    --tone: #475569;
    --tone-bg: #f8fafc;
    --tone-border: #cbd5e1;
    --tone-deep: #334155
}

.training-track:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px -8px rgba(15, 23, 42, 0.18);
    border-color: var(--tone-border)
}

.training-track::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: var(--tone)
}

.training-track__head {
    display: flex;
    gap: 13px;
    align-items: flex-start;
    padding: 16px 18px 12px 21px
}

.training-track__num {
    width: 32px;
    height: 32px;
    flex: none;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13.5px;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
    background: var(--tone-bg);
    color: var(--tone-deep);
    border: 1px solid var(--tone-border)
}

.training-track__titles {
    flex: 1;
    min-width: 0
}

.training-track__title {
    font-size: 15.5px;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.25
}

.training-track__blurb {
    font-size: 12.5px;
    color: #64748b;
    margin-top: 4px;
    line-height: 1.45
}

.training-track__screens {
    display: flex;
    gap: 5px;
    flex-wrap: wrap;
    padding: 0 18px 12px 21px
}

.training-track__gate {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 18px 8px 21px;
    font-size: 11.5px;
    line-height: 1.45;
    color: #92400e;
    background: #fef3c7;
    border-top: 1px dashed #fcd34d;
    border-bottom: 1px dashed #fcd34d
}

.training-track__foot {
    margin-top: auto;
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    padding: 12px 18px 14px 21px;
    border-top: 1px solid #eef2f7;
    background: #fafbfc
}

.training-track__meta {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 11.5px;
    color: #94a3b8;
    font-variant-numeric: tabular-nums
}

.training-track__bar {
    width: 82px;
    height: 4px;
    flex: none;
    background: #eef2f7;
    border-radius: 999px;
    overflow: hidden
}

.training-track__bar span {
    display: block;
    height: 100%;
    border-radius: 999px;
    background: var(--tone)
}

.training-track__actions {
    margin-left: auto;
    display: flex;
    gap: 7px
}

.training-screen {
    font-size: 11px;
    font-weight: 600;
    padding: 3px 9px;
    border-radius: 999px;
    background: var(--tone-bg, #f8fafc);
    border: 1px solid var(--tone-border, #e5e7eb);
    color: var(--tone-deep, #475569);
    white-space: nowrap
}

.training-pill {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    background: #f8fafc;
    color: #64748b;
    border: 1px solid #e5e7eb
}

.training-pill--complete {
    background: #d1fae5;
    color: #065f46;
    border-color: #a7f3d0
}

.training-pill--in_progress {
    background: #fef3c7;
    color: #92400e;
    border-color: #fcd34d
}

.training-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 6px 12px;
    border: 0;
    border-radius: 9px;
    font-size: 12px;
    font-weight: 600;
    color: #fff;
    cursor: pointer;
    background: linear-gradient(135deg, var(--t-accent-soft), var(--t-accent));
    box-shadow: 0 4px 14px -4px rgba(15, 23, 42, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.28);
    transition: transform 0.15s, box-shadow 0.15s, background 0.15s
}

.training-btn:hover {
    background: linear-gradient(135deg, var(--t-accent), var(--t-accent-deep));
    box-shadow: 0 10px 22px -8px rgba(15, 23, 42, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.28);
    transform: translateY(-1px);
    color: #fff
}

.training-btn--neutral {
    background: #fff;
    color: #475569;
    border: 1px solid #e5e7eb;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04)
}

.training-btn--neutral:hover {
    background: #f8fafc;
    color: #1e293b
}

