    --y-back: 7px;
    --x-back-end: 9px;
    --y-back-end: 0
}

.pos_body .grid-list .icon .dots i:nth-child(2) {
    --left: 13px;
    --x-middle: -12px;
    --y-middle: 5px;
    --x-end: -11px;
    --y-end: 7px;
    --x-back: -3px;
    --y-back: 1px;
