}

.pos_body .grid-list .icon .dots i:nth-child(3) {
    --top: 13px;
    --x-middle: 4px;
    --y-middle: -5px;
    --x-end: -2px;
    --y-end: -7px;
    --x-back: -5px;
    --y-back: 0px;
    --x-back-end: 9px;
    --y-back-end: 0
}

.pos_body .grid-list .icon .dots i:nth-child(4) {
    --left: 13px;
    --top: 13px;
    --x-middle: 0;
    --y-middle: -10px;
    --x-end: -11px;
    --y-end: -12px;
    --x-back: -14px;
    --y-back: -8px;
    --x-back-end: -9px;
    --y-back-end: 0
}

.pos_body .grid-list .icon .lines {
    --name: var(--lines-name, none);
    --duration: var(--lines-duration, .15s);
