    color: var(--color)
}

.pos_body .grid-list .text span {
    --y-default: 0;
    --o-default: 1;
    --y-active: -12px;
    --o-active: 0;
    display: block;
    opacity: var(--o-default);
    transform: translateY(var(--y-default)) translateZ(0);
    animation: var(--span-name, none) 0.4s ease forwards
}

.pos_body .grid-list .text span:last-child {
    --y-default: 12px;
    --o-default: 0;
    --y-active: 0;
    --o-active: 1;
    position: absolute;
    left: 0;
    top: 0
}

.pos_body .grid-list.animation {
    --span-name: text;
    --dots-name: back;
    --lines-name: scale-down
}

.pos_body .grid-list.animation .lines i {
    transform-origin: 0 50%
}

.pos_body .grid-list.animation .lines i:nth-child(3),
.pos_body .grid-list.animation .lines i:nth-child(4) {
    transform-origin: 100% 50%
}

.pos_body .grid-list.animation.active {
    --span-name: text-active;
    --dots-name: move;
    --lines-name: scale;
    --lines-duration: .15s;
    --lines-delay: .3s
}

.pos_body .grid-list.animation.active .lines i {
    transform-origin: 100% 50%
}

.pos_body .grid-list.animation.active .lines i:nth-child(3),
.pos_body .grid-list.animation.active .lines i:nth-child(4) {
    transform-origin: 0 50%
}

@keyframes text {
    0% {
        opacity: var(--o-active);
        transform: translateY(var(--y-active)) translateZ(0)
    }
    100% {
        opacity: var(--o-default);
        transform: translateY(var(--y-default)) translateZ(0)
    }
}

@keyframes text-active {
    0% {
        opacity: var(--o-default);
        transform: translateY(var(--y-default)) translateZ(0)
    }
    100% {
        opacity: var(--o-active);
        transform: translateY(var(--y-active)) translateZ(0)
    }
}

@keyframes move {
    50% {
        transform: translate(var(--x-middle, 0), var(--y-middle, 0)) scale(0.4)
    }
    100% {
        transform: translate(var(--x-end, 0), var(--y-end, 0)) scale(0.4)
    }
}

@keyframes back {
    0%,
    15% {
        transform: translate(var(--x-end, 0), var(--y-end, 0)) scale(0.4)
    }
    50% {
        transform: translate(var(--x-back, 0), var(--y-back, 0)) scale(0.5)
    }
    100% {
        transform: translate(var(--x-back-end, 0), var(--y-back-end, 0)) scale(1)
    }
}

@keyframes scale {
    100% {
        transform: translateY(20%) translateZ(0) scaleX(1)
    }
}

@keyframes scale-down {
    0% {
        transform: translateY(20%) translateZ(0) scaleX(1)
    }
    100% {
